		if (ReferenceSingleton<LocalizationManager>.instance != null)
		{
			UnityEngine.Object.Destroy(base.gameObject);
		}
		else
		{
			UnityEngine.Object.DontDestroyOnLoad(base.gameObject);
		}
		base.Awake();
	}

	private IEnumerator Start()
	{
		LocalizationSettings.SelectedLocaleChanged += SelectedLanguage;
		battleTable.TableChanged += BattleTableChanged;
		yield return battleTable.GetTable();
		OnLocalizedTableLoaded.Raise();
		localizationTableLoaded = true;
	}

	private void SelectedLanguage(Locale locale)
	{
