	public string GetLocalizedString(string ID)
	{
		try
		{
			return currentBattleTable[ID].LocalizedValue;
		}
		catch (Exception)
		{
			Debug.Log($"GetLocalizedString failed. -> ID: {ID}");
			return $"GetLocalizedString failed. -> ID: {ID}";
		}
	}

