	public string GetLocalizedEffectOwnerReceiveEffectFormatted(Effect effect, int amount)
	{
		string arg = amount.ToString();
		if (amount == EffectsValues.NO_VALUE || amount == -1)
		{
			arg = GetLocalizedX();
		}
		else if (amount >= EffectsValues.INFINITY)
		{
			return Smart.Format(effectCustomDescription.ReplacePreposition(GetLocalizedString("EffectOwnerReceiveEffect")), Smart.Format(GetLocalizedInfinity(), effect.GetEffectName()));
		}
		return Smart.Format(GetLocalizedString("EffectOwnerReceiveEffect"), arg, effect.GetEffectName());
	}

