	public string GetLocalizedXTimesFormatted(string firstArgument, int amount, string bonusAmountEquation = "")
	{
		if (amount == -1 || amount == EffectsValues.NO_VALUE)
		{
			amount = 999999999;
			return Smart.Format(GetLocalizedString("XTimes"), firstArgument, amount).Replace("999999999", GetLocalizedX());
		}
		if (bonusAmountEquation != "")
		{
			int num = 999999999;
			return Smart.Format(GetLocalizedString("XTimes"), firstArgument, num).Replace("999999999", bonusAmountEquation);
		}
		return Smart.Format(GetLocalizedString("XTimes"), firstArgument, amount);
	}

