	private string GetLocalizedWhereXFormatted(string id, string firstArgument, bool y, string thirdArgument, bool removeThirdArgument = false)
	{
		if (removeThirdArgument)
		{
			return Smart.Format(GetLocalizedString(id).Replace(" {2}", "").Replace("{2}", ""), firstArgument, y ? GetLocalizedY() : GetLocalizedX());
		}
		return Smart.Format(GetLocalizedString(id), firstArgument, y ? GetLocalizedY() : GetLocalizedX(), thirdArgument);
	}

