	public string GetChapterAppearanceText(List<int> chapterMute)
	{
		string text = "";
		if (chapterMute.Count > 0)
		{
			for (int i = 1; i < 4; i++)
			{
				if (!chapterMute.Contains(i))
				{
					text = text + "C" + i;
				}
			}
			if (ReferenceSingleton<AssetsReference>.Instance.MapHandler.IsOnAstreasHeart && !chapterMute.Contains(3))
			{
				text += "C4";
			}
		}
		return text;
	}

